//! g-xTB v1.1 at finite electronic temperatures (Fermi smearing) against the 1.1.0 program
//! (`gxtb -c mol.xyz -tel T`; data in tests/reference/etemp.json, generated by
//! scripts/make_reference_etemp.py), and the analytic gradients against finite differences.

use axtb_gxtb::scf::{Conventions, ScfOptions, Setup};
use serde_json::Value;
use std::path::{Path, PathBuf};

fn tests() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests")
}

fn rows() -> Vec<Value> {
    let doc: Value =
        serde_json::from_str(&std::fs::read_to_string(tests().join("reference/etemp.json")).unwrap()).unwrap();
    doc["rows"].as_array().unwrap().clone()
}

fn molecule(group: &str, name: &str) -> axtb::Molecule {
    let d = if group == "extra" {
        tests().join("reference_v2/etemp/extra").join(name)
    } else {
        tests().join("reference").join(name)
    };
    let input: Value = serde_json::from_str(&std::fs::read_to_string(d.join("input.json")).unwrap()).unwrap();
    let xyz = std::fs::read_to_string(d.join("mol.xyz")).unwrap();
    let uhf = input["uhf"].as_u64().unwrap() as usize;
    axtb_gxtb::read_xyz(&xyz, input["charge"].as_f64().unwrap(), Some(uhf)).unwrap()
}

/// Program mode at 300, 1000, 3000 and 5000 K: total energies and SCF iterations as the
/// program's (Fe4, whose SCF takes 45-941 iterations or fails, is reported only).
#[test]
fn etemp_matches_program() {
    let mut worst: f64 = 0.0;
    let mut bad = Vec::new();
    for row in rows() {
        let (group, name) = (row["group"].as_str().unwrap(), row["name"].as_str().unwrap());
        let etemp = row["etemp"].as_f64().unwrap();
        let label = format!("{name} {etemp} K");
        let mol = molecule(group, name);
        let opts = ScfOptions { conventions: Conventions::Gxtb, etemp, ..Default::default() };
        let res = Setup::new(&mol).unwrap().scf(&opts);
        let sensitive = name == "Fe4";
        if !row["converged"].as_bool().unwrap() {
            println!("{label:28} program SCF fails; ours: {}", if res.is_err() { "fails" } else { "converges" });
            continue;
        }
        let r = match res {
            Ok(r) => r,
            Err(e) => {
                println!("{label:28} FAILED {e}");
                if !sensitive {
                    bad.push(label);
                }
                continue;
            }
        };
        let de = r.energies.total - row["total_energy"].as_f64().unwrap();
        let it = row["scf_iterations"].as_u64().unwrap() as usize;
        println!("{label:28} dE {de:9.1e} it {:3}/{it:3} -TS {:10.3e}", r.iterations, r.energies.entropy);
        if sensitive {
            continue;
        }
        worst = worst.max(de.abs());
        if r.iterations != it {
            bad.push(label);
        }
    }
    println!("worst energy {worst:e}, mismatches {bad:?}");
    assert!(bad.is_empty(), "iterations or failures differ: {bad:?}");
    assert!(worst < 1e-10, "total energy {worst:e}");
}

fn tight(c: Conventions, etemp: f64) -> ScfOptions {
    ScfOptions { energy_tol: Some(1e-13), density_tol: Some(1e-11), conventions: c, etemp, ..Default::default() }
}

/// Analytic gradients in both conventions at 5000 K against 5-point finite differences of the
/// free energy (program mode: the Z-vector response of the program's Fock matrix with
/// fractional occupations and Fermi-level shifts).
#[test]
fn etemp_gradient_matches_finite_differences() {
    let cases = std::env::var("V11_ETEMP_GRAD")
        .unwrap_or("extra/N2_stretched,reference/tetrachlorocuprate,reference/mesyl_chloride".into());
    for rel in cases.split(',') {
        let (group, name) = rel.split_once('/').unwrap();
        let mol = molecule(group, name);
        for c in [Conventions::Gxtb, Conventions::Axtb] {
            // program mode: its gradient is not stationary in the density, so the SCF's convergence
            // error enters the energies at first order. Converged to 1e-11 it was the error of the
            // differences at h = 5e-4 (CuCl4 2.2e-9 to 4.2e-9 depending on round-off; 6.4e-10 at
            // 1e-13). Stencils with h >= 7.5e-4 cross a separate non-smoothness of the program-mode
            // energy (~1e-8 in the differences, at any SCF threshold).
            let opts = match c {
                Conventions::Gxtb => ScfOptions { density_tol: Some(1e-13), max_iter: 1000, ..tight(c, 5000.0) },
                Conventions::Axtb => tight(c, 5000.0),
            };
            let setup = Setup::new(&mol).unwrap();
            let r = setup.scf(&opts).unwrap();
            let g = setup.gradient(&r).unwrap();
            let e = |m: &axtb::Molecule| Setup::new(m).unwrap().scf(&opts).unwrap().energies.total;
            let h = 5e-4;
            let mut worst: f64 = 0.0;
            for a in 0..mol.nat() {
                for x in 0..3 {
                    let at = |d: f64| {
                        let mut m = mol.clone();
                        m.positions[a][x] += d;
                        e(&m)
                    };
                    let fd = (8.0 * (at(h) - at(-h)) - (at(2.0 * h) - at(-2.0 * h))) / (12.0 * h);
                    worst = worst.max((fd - g[a][x]).abs());
                }
            }
            println!("{name:20} {c:?} 5000 K  -TS {:.3e}  max |analytic - FD| = {worst:.2e}", r.energies.entropy);
            let tol = if c == Conventions::Gxtb { 3e-9 } else { 2e-9 };
            assert!(worst < tol, "{name} {c:?}: {worst:e}");
        }
    }
}

/// The program's numerical gradients (`-grad -symthr 0 -tel T` with tightened SCF thresholds:
/// central differences with h = 0.0075 bohr, the first atom minus the sum of the others) are
/// our central differences with the same step (its displaced energies are reproduced), and the
/// analytic gradient is their Richardson extrapolation.
#[test]
fn etemp_gradient_matches_program() {
    let (mut worst_fd, mut worst_rich): (f64, f64) = (0.0, 0.0);
    let h = 0.0075;
    for row in rows().iter().filter(|r| r.get("gradient_tight").is_some()) {
        let (group, name) = (row["group"].as_str().unwrap(), row["name"].as_str().unwrap());
        let etemp = row["etemp"].as_f64().unwrap();
        let c = Conventions::Gxtb;
        let mol = molecule(group, name);
        let setup = Setup::new(&mol).unwrap();
        let g = setup.gradient(&setup.scf(&tight(c, etemp)).unwrap()).unwrap();
        let gp = row["gradient_tight"].as_array().unwrap();
        let e = |a: usize, k: usize, d: f64| {
            let mut m = mol.clone();
            m.positions[a][k] += d;
            Setup::new(&m).unwrap().scf(&tight(c, etemp)).unwrap().energies.total
        };
        let (mut dfd, mut drich): (f64, f64) = (0.0, 0.0);
        for a in 0..mol.nat() {
            for k in 0..3 {
                let fd = |h: f64| (e(a, k, h) - e(a, k, -h)) / (2.0 * h);
                let (f1, f2) = (fd(h), fd(h / 2.0));
                if a > 0 {
                    dfd = dfd.max((gp[a][k].as_f64().unwrap() - f1).abs());
                }
                drich = drich.max((g[a][k] - (4.0 * f2 - f1) / 3.0).abs());
            }
        }
        println!(
            "{name:20} {etemp} K  |program - our central differences| {dfd:.2e}  |analytic - extrapolated| {drich:.2e}"
        );
        worst_fd = worst_fd.max(dfd);
        worst_rich = worst_rich.max(drich);
    }
    // [CuCl4]2-: 2e-9 (its d-d AES Fock elements differ from the program by ~1e-9, spec 4.16)
    assert!(worst_fd < 3e-9, "{worst_fd:e}");
    assert!(worst_rich < 1e-7, "{worst_rich:e}");
}
